<script setup>
import { onBeforeUnmount, onMounted, ref } from 'vue'
import { ArrowUpRight, ClipboardList, Package, RefreshCw, Store, Truck } from 'lucide-vue-next'
import { useRouter } from 'vue-router'
import { loadAdminOrders, loadAdminStats, subscribeToOrders } from '../services/adminOperationsService'
const router = useRouter(); const stats = ref(null); const recent = ref([]); const loading = ref(true); const error = ref(''); let unsubscribe
const cards = [{ key: 'restaurants', label: 'Restaurantes activos', icon: Store, link: '/admin/restaurantes' }, { key: 'products', label: 'Productos disponibles', icon: Package, link: '/admin/productos' }, { key: 'pending', label: 'Pedidos pendientes', icon: ClipboardList, link: '/admin/pedidos' }, { key: 'preparing', label: 'En preparación', icon: Truck, link: '/admin/pedidos' }, { key: 'onTheWay', label: 'En camino', icon: Truck, link: '/admin/pedidos' }, { key: 'delivered', label: 'Entregados', icon: ClipboardList, link: '/admin/pedidos' }]
async function load() { loading.value = true; try { [stats.value, recent.value] = await Promise.all([loadAdminStats(), loadAdminOrders()]); recent.value = recent.value.slice(0, 6) } catch (e) { error.value = e.message || 'No se pudo cargar el resumen.' } finally { loading.value = false } }
onMounted(async () => { await load(); unsubscribe = subscribeToOrders(load) }); onBeforeUnmount(() => unsubscribe?.())
</script>
<template><section class="admin-view"><div class="admin-view-heading"><div><span class="admin-eyebrow">RESUMEN DEL SISTEMA</span><h2>Dashboard</h2><p>Una vista rápida de la operación actual.</p></div><button class="admin-icon-button" @click="load"><RefreshCw :size="18" /></button></div><p v-if="error" class="admin-alert">{{ error }}</p><div v-if="loading" class="admin-empty">Cargando datos reales…</div><template v-else><div class="admin-stat-grid"><button v-for="card in cards" :key="card.key" class="admin-stat-card" @click="router.push(card.link)"><span><component :is="card.icon" :size="18" /></span><strong>{{ stats[card.key] }}</strong><small>{{ card.label }}</small><ArrowUpRight :size="16" /></button></div><section class="admin-panel"><div class="admin-panel-heading"><div><h3>Pedidos recientes</h3><p>Actualizados automáticamente con Realtime.</p></div><RouterLink to="/admin/pedidos">Ver todos</RouterLink></div><div v-if="!recent.length" class="admin-empty">Todavía no hay pedidos registrados.</div><div v-else class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Pedido</th><th>Restaurante</th><th>Total</th><th>Estado</th></tr></thead><tbody><tr v-for="order in recent" :key="order.id" @click="router.push('/admin/pedidos')"><td>#{{ order.numero }}</td><td>{{ order.restaurantes?.nombre || '—' }}</td><td>${{ Number(order.total).toFixed(2) }}</td><td><span class="admin-status-pill" :data-status="order.estado">{{ order.estado }}</span></td></tr></tbody></table></div></section></template></section></template>
